package fi.alavesa.cctv.hud;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.kyori.adventure.key.Key;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.TextComponent;
import net.kyori.adventure.text.format.ShadowColor;
import net.kyori.adventure.text.format.Style;
import net.kyori.adventure.text.format.TextColor;

/**
 * Lays CCTV HUD text out at absolute positions inside ONE text component (sent as the title subtitle).
 *
 * <p>How positioning works (fonts generated by tools/gen_hud_font.py):
 * <ul>
 *   <li>vertical: each screen row is its own font (cctv:hud_&lt;row&gt;, cctv:hud_big_&lt;row&gt;) whose only
 *       difference is the glyph ascent;</li>
 *   <li>horizontal: every glyph is exactly {@link #ADVANCE} font px wide (monospace by construction), and
 *       cctv:space has signed spaces of ±2^n px, so the cursor can be moved anywhere;</li>
 *   <li>the line always ends with the cursor moved back to 0, so the client's centring (draw at -width/2) puts our
 *       x = 0 exactly at the screen centre.</li>
 * </ul>
 * One font px is 2 GUI px in the subtitle.
 *
 * <p>Marker: every glyph is coloured #0CC7xx (see the shader includes), shadow off.
 */
public final class HudText {

    public static final int ADVANCE = 7;
    public static final int BIG_ADVANCE = 13;
    public static final int ROWS = 14;
    public static final int BIG_ROWS = 6;

    public static final int FLICKER = 1, GLITCH = 2, ABERRATION = 4, SCANLINES = 8, BLINK = 16;
    public static final int WHITE = 0, RED = 1, GREEN = 2, AMBER = 3, GREY = 4, CYAN = 5, DARK = 6, BLACK = 7;

    public static final char REC_DOT = '';
    public static final char BAR_FULL_1 = '';
    public static final char BAR_EMPTY_1 = '';
    public static final char BLOCK = '';
    public static final char POINTER = '';

    private static final Key SPACE = Key.key("cctv", "space");
    private static final Key[] ROW_FONTS = new Key[ROWS];
    private static final Key[] BIG_FONTS = new Key[BIG_ROWS];

    static {
        for (int i = 0; i < ROWS; i++) ROW_FONTS[i] = Key.key("cctv", "hud_" + i);
        for (int i = 0; i < BIG_ROWS; i++) BIG_FONTS[i] = Key.key("cctv", "hud_big_" + i);
    }

    private record Part(float x, int row, boolean big, String text, int palette, int flags) {
    }

    private final List<Part> parts = new ArrayList<>();

    /** Text whose left edge is at x (font px from the screen centre). */
    public HudText left(float x, int row, String text, int palette, int flags) {
        parts.add(new Part(x, row, false, clean(text), palette, flags));
        return this;
    }

    /** Text whose right edge is at x. */
    public HudText right(float x, int row, String text, int palette, int flags) {
        String t = clean(text);
        parts.add(new Part(x - width(t, false), row, false, t, palette, flags));
        return this;
    }

    /** Text centred on x. */
    public HudText center(float x, int row, String text, int palette, int flags) {
        String t = clean(text);
        parts.add(new Part(x - width(t, false) / 2f, row, false, t, palette, flags));
        return this;
    }

    /** Double-size text centred on x, on a big row. */
    public HudText bigCenter(float x, int bigRow, String text, int palette, int flags) {
        String t = clean(text);
        parts.add(new Part(x - width(t, true) / 2f, bigRow, true, t, palette, flags));
        return this;
    }

    /**
     * A solid panel of {@code cells} double-size blocks centred on x (drawn behind later parts). Blocks are 12 px
     * wide but advance 13, so each is placed separately at a 12 px pitch to close the gaps.
     */
    public HudText bigPanel(float x, int bigRow, int cells, int palette) {
        int n = Math.max(1, cells);
        float pitch = BIG_ADVANCE - 1;
        float start = x - n * pitch / 2f;
        for (int i = 0; i < n; i++) {
            parts.add(new Part(start + i * pitch, bigRow, true, String.valueOf(BLOCK), palette, 0));
        }
        return this;
    }

    public boolean isEmpty() {
        return parts.isEmpty();
    }

    public Component build() {
        TextComponent.Builder out = Component.text();
        float cursor = 0;
        for (Part p : parts) {
            space(out, p.x - cursor);
            Key font = p.big ? BIG_FONTS[Math.clamp(p.row, 0, BIG_ROWS - 1)] : ROW_FONTS[Math.clamp(p.row, 0, ROWS - 1)];
            out.append(Component.text(p.text, Style.style(marker(p.palette, p.flags), ShadowColor.none())
                    .font(font)));
            cursor = p.x + width(p.text, p.big);
        }
        space(out, -cursor);
        return out.build();
    }

    public static TextColor marker(int palette, int flags) {
        return TextColor.color(0x0C, 0xC7, ((palette & 7) << 5) | (flags & 31));
    }

    public static float width(String text, boolean big) {
        return text.codePointCount(0, text.length()) * (big ? BIG_ADVANCE : ADVANCE);
    }

    /** Upper-case printable ASCII plus our graphics; anything else becomes '?' (the font has nothing else). */
    public static String clean(String s) {
        StringBuilder b = new StringBuilder(s.length());
        for (char ch : s.toUpperCase(Locale.ROOT).toCharArray()) {
            b.append((ch >= 0x20 && ch < 0x7F) || (ch >= '' && ch <= '') ? ch : '?');
        }
        return b.toString();
    }

    /** Appends cctv:space glyphs adding up to px (0.5 px resolution). */
    private static void space(TextComponent.Builder out, float px) {
        int halves = Math.round(px * 2);
        if (halves == 0) return;
        boolean neg = halves < 0;
        int h = Math.abs(halves);
        StringBuilder s = new StringBuilder();
        if ((h & 1) != 0) s.append(neg ? '' : '');
        int whole = h >> 1;
        for (int n = 0; n < 10 && whole > 0; n++, whole >>= 1) {
            if ((whole & 1) != 0) s.append((char) ((neg ? 0xF100 : 0xF000) + n));
        }
        while (whole > 0) { // beyond 1023 px: each remaining unit is 1024 px = two 512 px steps
            s.append((char) ((neg ? 0xF100 : 0xF000) + 9)).append((char) ((neg ? 0xF100 : 0xF000) + 9));
            whole -= 1;
        }
        out.append(Component.text(s.toString(), Style.style().font(SPACE).build()));
    }
}
